#!/usr/bin/env node
/* 生成各章「参考资料」条目（docs/NN-chapter/999-references.md）。
 *
 * 单一事实来源：scripts/references-data.json（键 = 章目录名）。
 * 每章的 volume/layer/track/stage/difficulty 元数据自动从该章 index.md 抄写，
 * 保证与 validate.mjs 的新课元数据闸门一致。
 *
 * 用法：node scripts/gen-references.mjs [--check]
 *   默认写入；--check 只对比是否为最新（CI/闸门可用）。
 *
 * 注意：999-references.md 不进知识图谱（gen-graph.mjs 排除）、
 * 不进独立阅读前端课程列表（ui/server.mjs 排除），
 * 但会进 Docusaurus 侧边栏（autogenerated 按文件名垫底）与全站搜索。
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const scriptDir = path.dirname(fileURLToPath(import.meta.url));
const docsRoot = path.join(scriptDir, '..', 'docs');
const dataFile = path.join(scriptDir, 'references-data.json');
const checkMode = process.argv.includes('--check');

const data = JSON.parse(fs.readFileSync(dataFile, 'utf8'));

function parseFrontMatter(text) {
  const m = text.match(/^---\r?\n([\s\S]*?)\r?\n---/);
  if (!m) return {};
  const out = {};
  let key = null;
  for (const line of m[1].split(/\r?\n/)) {
    const bullet = line.match(/^\s*-\s*(.+)$/);
    if (bullet && key && Array.isArray(out[key])) {
      out[key].push(bullet[1].trim());
      continue;
    }
    const kv = line.match(/^([A-Za-z_][\w-]*):\s*(.*)$/);
    if (!kv) continue;
    key = kv[1];
    const raw = kv[2].trim();
    const inline = raw.match(/^\[(.*)\]$/);
    if (inline) {
      out[key] = inline[1]
        ? inline[1].split(',').map((s) => s.trim()).filter(Boolean)
        : [];
      key = null;
    } else if (raw === '') {
      out[key] = [];
    } else {
      out[key] = raw.replace(/^["']|["']$/g, '');
      key = null;
    }
  }
  return out;
}

/* 读者可见标题不带编号前缀（写课规范第 6 条），从章 index 的 title 提取纯章名 */
function plainChapterTitle(indexFm, dirName) {
  const t = indexFm?.title || '';
  const seg = t.split('·').map((s) => s.trim()).filter(Boolean);
  if (seg.length >= 2) return seg[seg.length - 1];
  return dirName.replace(/^\d+-/, '');
}

function paperFence(entry) {
  const lines = [
    '# @title: ' + entry.t,
    '# @authors: ' + entry.a,
    '# @year: ' + String(entry.y),
    '# @venue: ' + entry.v,
    '# @tag: ' + (entry.g || '论文'),
    '# @desc: ' + entry.d,
    '# @page: ' + entry.p,
  ];
  if (entry.f) {
    /* PDF 链接以 base64 写入条目：静态 HTML 源码不再直接可读，
       下载按钮由 enhancer.js 在浏览器端解码。这是「避免源码一眼可得」的
       混淆手段而非加密（安全边界声明见 REGISTRATION.md）。 */
    lines.push('# @pdf64: ' + Buffer.from(entry.f, 'utf8').toString('base64'));
  }
  return '```paper\n' + lines.join('\n') + '\n```';
}

const chapterDirs = fs
  .readdirSync(docsRoot, { withFileTypes: true })
  .filter((d) => d.isDirectory() && /^\d+/.test(d.name))
  .map((d) => d.name)
  .sort((a, b) => parseInt(a, 10) - parseInt(b, 10));

let written = 0;
let unchanged = 0;
const problems = [];

for (const dir of chapterDirs) {
  const indexPath = path.join(docsRoot, dir, 'index.md');
  if (!fs.existsSync(indexPath)) continue;
  const indexFm = parseFrontMatter(fs.readFileSync(indexPath, 'utf8'));
  const entries = data[dir];
  if (!entries || !entries.length) {
    problems.push(`${dir}: references-data.json 缺少该章条目（已跳过生成）`);
    continue;
  }

  const metaLines = [];
  if (indexFm.volume != null && indexFm.volume !== '') metaLines.push(`volume: ${indexFm.volume}`);
  if (indexFm.layer) metaLines.push(`layer: ${indexFm.layer}`);
  if (Array.isArray(indexFm.track) && indexFm.track.length) {
    metaLines.push('track:');
    for (const t of indexFm.track) metaLines.push(`  - ${t}`);
  }
  if (indexFm.stage) metaLines.push(`stage: ${indexFm.stage}`);
  if (indexFm.difficulty != null && indexFm.difficulty !== '') {
    metaLines.push(`difficulty: ${indexFm.difficulty}`);
  }

  const chTitle = plainChapterTitle(indexFm, dir);
  const body = [
    '---',
    `title: ${chTitle} · 参考资料`,
    `description: 第 ${parseInt(dir, 10)} 章涉及的核心论文、原著与延伸阅读一览。`,
    ...metaLines,
    '---',
    '',
    `# ${chTitle} · 参考资料`,
    '',
    '本章涉及的核心论文、原著与延伸阅读，按课程推进顺序整理。',
    '',
    '「文献页面」与 PDF 下载对所有人开放；需要同步学习进度时可在「登录」页用默认账号进入自己的进度空间。',
    '',
    entries.map(paperFence).join('\n\n'),
    '',
  ].join('\n');

  const outPath = path.join(docsRoot, dir, '999-references.md');
  if (fs.existsSync(outPath)) {
    const prev = fs.readFileSync(outPath, 'utf8');
    if (prev === body) {
      unchanged += 1;
      continue;
    }
  }
  if (!checkMode) fs.writeFileSync(outPath, body, 'utf8');
  written += 1;
}

if (problems.length) {
  for (const p of problems) console.log('⚠ ' + p);
}

if (checkMode && written > 0) {
  console.log(`✗ ${written} 个 999-references.md 落后于 references-data.json，请运行 node scripts/gen-references.mjs`);
  process.exit(1);
}
console.log(
  `✔ 参考资料条目：${checkMode ? '落后 ' + written : '已写入 ' + written} / 未变化 ${unchanged}（共 ${chapterDirs.length} 章）`,
);
